const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],icon=id=>`<svg><use href="#${id}"/></svg>`;
const skillIcons=['wind','dash','orb','ult'];
function portrait(i){const h=HEROES[i],hair=['#f0f6e8','#9d74b6','#282a2b','#56647c','#253d35'][i],skin=i===2?'#995b3c':i===3?'#52637b':'#e8c4ab';return `<svg viewBox="0 0 60 68" xmlns="http://www.w3.org/2000/svg"><path d="M9 65V51c0-11 42-11 42 0v14" fill="${h.color}"/><path d="M19 47h22v14H19z" fill="${i===2?'#f4e9d3':h.color}"/><path d="M13 26c0-20 34-20 34 0v14c0 19-34 19-34 0Z" fill="${skin}"/><path d="M12 31V19C13 2 47 2 48 19v12L35 15 23 27Z" fill="${hair}"/>${i===0?'<circle cx="33" cy="7" r="6" fill="#eef6e9"/>':i===1?'<path d="M10 23 7 50l11-5V24m25 0v21l10 5-3-27" fill="#8b5f9c"/><path d="m40 14 6-4 3 5-7 3" fill="#f4c4ed"/>':i===2?'<path d="m17 12 1-9 6 6 5-8 5 8 5-6 3 10Z" fill="#2c2e2d"/>':i===4?'<circle cx="31" cy="6" r="6" fill="#273d34"/>':''}${i===3?'<path d="M17 28h26v14H17z" fill="#222d43"/><path d="M23 33h14v5H23z" fill="#bd9afa"/>':'<path d="M21 34h4v4h-4zm14 0h4v4h-4z" fill="#2b4640"/><path d="M27 44h6" stroke="#b77e6d" stroke-width="2"/>'}</svg>`;}
let selectedMode='clutch',weaponFilter='全部';
const modeText={clutch:{title:'这一次，由你翻盘。',description:'一分钟残局 · 1v2 / 1v3 · 技能破局',button:'挑战一分钟残局'},spike:{title:'五回合，决胜古城。',description:'800信用点起步 · 买枪配装 · 安装与拆除',button:'部署爆破行动'},moba:{title:'三路推进，击碎水晶。',description:'兵线与野区 · 英雄协同 · 破塔推晶',button:'出征 MOBA 战场'}};
function refreshMode(){const m=modeText[selectedMode];$('#modeHeadline').textContent=m.title;$('#modeDescription').textContent=m.description;$('#start span').textContent=m.button;$('.panel-note').textContent=selectedMode==='clutch'?'独自破解三种残局 · 关间选择强化 · 失败立即重试':'你与 4 名 AI 队友，迎战 5 名 AI 对手。';$('.start-note').textContent=selectedMode==='clutch'?'单关 50–70 秒 · 先选武器与战术装置':'单人 5V5 · 点击启动音效与全屏';}
let hero=0,difficulty='normal',game=null,view,audio=new AudioManager(),controls,paused=false,modalMode='',last=performance.now(),uiAt=0,eventSeen=new WeakSet(),noticesUntil=0,feed=[],rotated=matchMedia('(orientation:portrait)').matches,frameTimes=[],fps=60,autoPaused=false;
function choose(i){hero=i;const h=HEROES[i];$$('.hero-option').forEach((b,j)=>b.classList.toggle('selected',i===j));$('#heroEnglish').textContent=h.en;$('#heroName').textContent=h.name;$('#heroRole').textContent=h.role;$('.panel-kicker span').textContent=`0${i+1} / 05`;$('#previewSkills').innerHTML=h.skills.map((n,k)=>`<div title="${h.desc[k]}">${icon(skillIcons[k])}${n}</div>`).join('');if(view)view.chooseHero(i);audio.play('cast',i);}
$('#heroPicker').innerHTML=HEROES.map((h,i)=>`<button class="hero-option ${i===0?'selected':''}" data-hero="${i}" aria-label="选择${h.name}"><div class="portrait">${portrait(i)}</div><span>${h.name}</span></button>`).join('');$$('[data-hero]').forEach(b=>b.onclick=()=>choose(+b.dataset.hero));$$('[data-diff]').forEach(b=>b.onclick=()=>{difficulty=b.dataset.diff;$$('[data-diff]').forEach(x=>x.classList.toggle('selected',x===b));});
$$('[data-mode]').forEach(b=>b.onclick=()=>{selectedMode=b.dataset.mode;refreshMode();$$('[data-mode]').forEach(x=>x.classList.toggle('selected',x===b));});
function pause(v){paused=v;autoPaused=false;controls?.reset();audio.pause(v||!game||game.winner!==null||rotated);}
function modal(content,mode='help'){modalMode=mode;$('.modal-card').classList.toggle('buy-card',mode==='buy');$('#modalContent').innerHTML=content;$('#modal').classList.remove('hidden');if(game)pause(true);}
function closeModal(){if(['result','buy','round','brief'].includes(modalMode))return;$('#modal').classList.add('hidden');if(game)pause(false);}
$('#closeModal').onclick=closeModal;$('#modal').onclick=e=>{if(e.target===$('#modal'))closeModal();};
function help(){modal(`<div class="tactical-help"><h3>2.3 一分钟残局</h3><p>独自挑战三关：B点回防拆包、C点守包反击、A点限时清场。先选枪与一次性装置；获胜选择强化带入下一关。死亡立即结算，可重试本关。三星与通关分数仅在本机记录。</p></div><div class="tactical-help"><h3>2.1 战术协作</h3><p>小地图下方可命令集结A/B/C、跟随或守住当前位置。「自主」恢复默认分工。爆破购买阶段三选一战术装置，每回合按Y或点击一次：侦察、急救或超频。靠近掉落枪按X拾取，保留余弹；阵亡后仍可下达包点指令。</p></div><div class="eyebrow">LOTUS / FIELD GUIDE</div><h2>双模式，立体古城。</h2><h3>SPIKE 爆破</h3><p>固定打满 5 回合，比较胜场。首回合 800，购买枪械与护甲后出发。胜方 +3000，连败奖励 1900 / 2400 / 2900，击杀 +200，安装后进攻方 +300；上限 9000。存活保枪保甲，阵亡下回合恢复标配。第 3 回合交换攻守。</p><p>进攻方携带 Spike，到 A/B/C 黄色圈内静止长按「安包 G」4 秒。防守方靠近 Spike 长按 7 秒拆除，半程检查点保留。安装后 45 秒引爆；安装前倒计时 100 秒。回合内不复活，阵亡后观战队友。包点有可摧毁的防守炮台。</p><h3>操作</h3><p>手机左摇杆移动，右侧按住开火、四技能。安拆、换弹、机关在摇杆旁独立分区。电脑 WASD 移动，空格射击，Q/E/R/F 技能，G 长按安拆，T 换弹，Shift 精准瞄准，Tab 查看购买，X 机关。点击敌人锁定目标；停步瞄准的首发可造成头部伤害，移动和持续连射扩大散布。枪械射速、伤害衰减、弹匣和换弹有差异，射程与命中按俯视玩法改编。</p><h3>MOBA 推晶</h3><p>三路兵线、双塔、水晶与五类野区 buff，摧毁敌方水晶获胜。回城 B，死亡后复活。小兵采用黄紫色伙伴外观的原创低模设计。</p><h3>古城机关</h3><p>根据 Lotus 平面通路重建 A/B/C、连接廊与出生区；A/C 旋转门靠近 X 打开 8 秒，A–B 脆弱墙可用技能打碎，A Drop 为静音单向落差。高低差与建筑按低模玩法近似，并非原版场景逐面复刻。</p><p>iPhone 推荐 Safari 添加到主屏幕，横放手机。低端设备可在设置中关闭动态阴影。</p><p style="font-size:10px;opacity:.65">个人学习原型 · 非官方作品 · 原创模型与音效替代 · 不具有 Riot 商业授权。</p>`);}
$('#help').onclick=help;
function settings(){if(!game)return;modal(`<div class="eyebrow">TACTICAL PAUSE</div><h2>稍作休整。</h2><p>对局已暂停。${game.difficulty==='easy'?'简单':game.difficulty==='hard'?'困难':'普通'}人机 · 当前 ${fmt(game.time)} · ${Math.round(fps)} FPS</p><label>技能与环境音效 <input id="sfxVolume" type="range" min="0" max="1" step="0.05" value="${audio.sfxVolume}"></label><label>背景音乐 <input id="musicVolume" type="range" min="0" max="0.6" step="0.05" value="${audio.musicVolume}"></label><label>渲染精度<select id="quality"><option value="1">流畅 · 1×</option><option value="1.5" selected>清晰 · 最高 1.5×</option></select></label><label>动态阴影 <input id="shadows" type="checkbox" ${view.renderer.shadowMap.enabled?'checked':''}></label><div class="modal-buttons"><button id="resume">继续对局</button><button id="inHelp">查看玩法</button><button id="backLobby">返回选人</button></div><p style="font-size:9px;opacity:.7">手机建议横屏，必要时用浏览器菜单添加到主屏幕。低端设备可降低渲染精度。</p>`,'pause');$('#sfxVolume').oninput=e=>audio.setVolume('sfx',+e.target.value);$('#musicVolume').oninput=e=>audio.setVolume('music',+e.target.value);$('#quality').value=String(view.renderer.getPixelRatio()>1?1.5:1);$('#quality').onchange=e=>{view.renderer.setPixelRatio(Math.min(devicePixelRatio,+e.target.value));view.resize();};$('#shadows').onchange=e=>view.renderer.shadowMap.enabled=e.target.checked;$('#resume').onclick=closeModal;$('#inHelp').onclick=help;$('#backLobby').onclick=backLobby;}
function backLobby(){$('#blindOverlay').style.opacity='0';$('#blindOverlay').classList.remove('active');game=null;paused=false;$('#modal').classList.add('hidden');$('#lobby').classList.remove('hidden');$('#hud').classList.add('hidden');view.lobby=true;view.showcase.visible=true;for(const m of view.models.values())m.visible=false;for(const m of view.fx)m.visible=false;view.resize();audio.pause(true);controls.reset();}
function historyHTML(){return `<div class="round-history">${game.results.map(r=>`<span class="${r.winner===0?'won':'lost'}">R${r.round} ${r.winner===0?'胜':'负'} · ${r.reason}</span>`).join('')}</div>`;}
function gunIcon(w){return `<img class="weapon-art" src="./assets/weapons/${w.id==='knife'?'tactical-knife':w.id}.png" alt="${w.name} ${w.en} 原版默认枪型" loading="lazy" decoding="async">`;}
function showShop(){if(!game||game.mode!=='spike'||game.phase!=='buy')return;const p=game.player,cost=game.quote(),selected=GUNS[game.draft.gun],cats=['全部','手枪','冲锋枪','霰弹枪','步枪','狙击枪','机枪','近战'];modal(`<div class="buy-modal"><div class="buy-header"><div><div class="eyebrow">ROUND ${game.round+1} / 5 · ${game.role}</div><h2>购买阶段</h2></div><div class="wallet">¤ ${p.wallet}<small>可用信用点</small></div></div><div class="device-options">${Object.entries(DEVICES).map(([id,d])=>`<button data-device="${id}" aria-label="${d.name}：${d.desc}" class="${game.device===id?'selected':''}"><b>${d.name}</b><small>${d.desc}</small></button>`).join('')}</div><div class="loadout-presets"><span>快速配装</span><button data-preset="eco">经济保留</button><button data-preset="balanced">均衡配装</button><button data-preset="assault">火力优先</button><small>只选择，不扣款</small></div><div class="weapon-tabs">${cats.map(c=>`<button data-cat="${c}" class="${weaponFilter===c?'selected':''}">${c}</button>`).join('')}</div><div class="gun-grid">${WEAPONS.filter(w=>weaponFilter==='全部'||w.category===weaponFilter).map(w=>{const price=w.id===p.carryGun?0:w.price;return `<button class="gun-card ${w.id===selected.id?'selected':''} ${price>p.wallet?'unaffordable':''}" data-gun="${w.id}">${gunIcon(w)}<b>${w.name}</b><span>${w.category} · ${price===0?'已拥有 / 免费':'¤ '+price}</span><small>${w.mag?w.mag+' 发 · '+w.rate+'/秒 · '+w.body+' 伤害':'近身战术刀'}</small></button>`;}).join('')}</div><div class="armor-row">${[['keep','保留护甲',0],['light','轻甲 +25',400],['heavy','重甲 +50',1000]].map(([id,n,price])=>`<button data-armor="${id}" class="${game.draft.armor===id?'selected':''}">${n} · ¤ ${price}</button>`).join('')}</div><div class="buy-footer"><div><b>${selected.name} · ${selected.en}</b><small>${selected.hint} · 停步瞄准更准</small><span>本次 ¤ ${cost} · 剩余 ¤ ${p.wallet-cost}</span></div><button id="deployRound" class="primary" ${cost>p.wallet?'disabled':''}>确认装备 · 出发 ↗</button></div><p class="buy-note">存活保留枪甲 · 第3回合换边 · 安拆长按G / 手机左侧安拆键 · 原版枪图 © Riot Games · 个人学习 · 枪械为俯视角改编</p></div>`,'buy');$$('[data-preset]').forEach(b=>b.onclick=()=>{game.recommend(b.dataset.preset);showShop();});$$('[data-device]').forEach(b=>b.onclick=()=>{game.selectDevice(b.dataset.device);showShop();});$$('[data-cat]').forEach(b=>b.onclick=()=>{weaponFilter=b.dataset.cat;showShop();});$$('[data-gun]').forEach(b=>b.onclick=()=>{game.select(b.dataset.gun);showShop();});$$('[data-armor]').forEach(b=>b.onclick=()=>{game.select(game.draft.gun,b.dataset.armor);showShop();});$('#deployRound').onclick=()=>{if(game.ready()){$('#modal').classList.add('hidden');pause(false);view.renderer.domElement.focus({preventScroll:true});}};}
function roundPanel(ev){modal(`<div class="round-report"><div class="eyebrow">ROUND ${ev.round} / 5 · AFTER ACTION</div><h2>${ev.winner===0?'任务完成':'重新集结'}</h2><div class="report-score"><b>${ev.score[0]}</b><span>:</span><b>${ev.score[1]}</b><small>${ev.reason}</small></div><div class="report-metrics"><div><b>${ev.damage||0}</b><span>有效伤害</span></div><div><b>${ev.accuracy||0}%</b><span>射击命中率</span></div><div><b>${ev.objectives||0}</b><span>安拆参与</span></div><div><b>¤ ${ev.after}</b><span>下回合资金</span></div></div><div class="report-insight"><span>战术复盘</span><p>${ev.advice||''}</p></div>${ev.mvp?`<div class="round-mvp"><div class="portrait">${portrait(ev.mvp.hero)}</div><div><small>ROUND MVP · ${ev.mvp.team===0?'我方':'敌方'}</small><b>${HEROES[ev.mvp.hero].name}</b><span>${ev.mvp.kills} 击杀 · ${ev.mvp.damage} 伤害</span></div></div>`:''}<p class="report-economy">资金 ¤ ${ev.before} → ¤ ${ev.after} · ${ev.survived?'装备已保留':'下回合重新配装'}</p>${historyHTML()}<button id="nextRound" class="primary">下一回合 · 前往武器库 ↗</button></div>`,'round');$('#nextRound').onclick=()=>{game.nextRound();showShop();};}
async function start(stage=0,augments=[],history=[],missionSeed){const display=enterLandscape();const sound=audio.init();await Promise.allSettled([display,sound]);game=selectedMode==='clutch'?new ClutchGame(hero,difficulty,missionSeed??crypto.getRandomValues(new Uint32Array(1))[0],stage,augments,history):selectedMode==='spike'?new SpikeGame(hero,difficulty,crypto.getRandomValues(new Uint32Array(1))[0]):new LotusGame(hero,difficulty,crypto.getRandomValues(new Uint32Array(1))[0]);document.body.classList.toggle('spike-mode',game.mode==='spike');document.body.classList.toggle('clutch-mode',!!game.clutch);controls.aiming=false;eventSeen=new WeakSet();feed=[];view.start(game);$('#lobby').classList.add('hidden');$('#hud').classList.remove('hidden');$('#modal').classList.add('hidden');$('#deathNotice').classList.add('hidden');$('#hudPortrait').innerHTML=portrait(hero);$('#hudName').textContent=HEROES[hero].name;$$('[data-skill]').forEach((b,i)=>{b.querySelector('b').textContent=HEROES[hero].skills[i];b.setAttribute('aria-label',HEROES[hero].skills[i]+'：'+HEROES[hero].desc[i]);});pause(false);if(!displayState().ios)view.renderer.domElement.focus({preventScroll:true});$('#recall span').textContent=game.mode==='spike'?'换弹 T':'回城 B';$('#attack b').textContent=game.mode==='spike'?'开火':'普攻';$('.scoreboard small').textContent=game.mode==='spike'?'固定 5 回合 · 最后比较胜场':'摧毁敌方水晶';if(game.clutch)clutchBrief();else if(game.mode==='spike')showShop();else announce('兵线即将抵达 · 保护我方水晶');}
$('#focusGame').onclick=()=>{action('activate');view.renderer.domElement.focus({preventScroll:true});hint('WASD移动 · 空格普攻 · Q/E/R/F技能 · X机关 · B回城');};$('#start').onclick=()=>start();$('#pause').onclick=settings;function iosGuide(){modal(`<div class="eyebrow">iPHONE / 主屏幕游玩</div><h2>用主屏幕模式打开</h2><p>Safari、Chrome或微信中的普通网页不能由游戏代码保证进入系统级全屏。</p><ol class="ios-steps"><li>先在 <b>Safari</b> 打开本游戏。</li><li>点击 Safari 的 <b>分享</b>（方框向上箭头；部分版本在“更多”内）。</li><li>选择 <b>添加到主屏幕</b>；如果出现“作为 Web App 打开”，请开启。</li><li>返回桌面，从「莲华古城」图标打开。关闭系统竖排方向锁定后横放手机。</li></ol><p>这样可去掉浏览器地址栏与标签栏。系统状态栏、底部手势条和旋转行为仍由 iOS 控制。</p><button class="primary" id="continueBrowser">先在浏览器继续试玩</button><p><a href="https://support.apple.com/guide/iphone/open-as-web-app-iphea86e5236/ios" target="_blank" rel="noopener">Apple 官方操作说明 ↗</a></p>`,'ios');$('#continueBrowser').onclick=closeModal;}
$('#iosGuide').onclick=iosGuide;if(displayState().ios&&!displayState().standalone)$('#iosGuide').classList.remove('hidden');
$('#fullscreen').onclick=async()=>{if(document.fullscreenElement||document.webkitFullscreenElement){try{if(document.exitFullscreen)await document.exitFullscreen();else document.webkitExitFullscreen?.();}catch{}view.resize();return;}const r=await enterLandscape();syncDisplay();if(r.fullscreen){hint(r.presentation==='standalone'?'已在主屏幕模式中 · 请横放手机':'已进入全屏');return;}if(r.ios){iosGuide();return;}hint('已铺满游戏窗口 · 系统全屏可用 Mac Control+Command+F / Windows F11');};$('#sound').onclick=()=>{audio.setEnabled(!audio.enabled);$('#sound').classList.toggle('muted',!audio.enabled);};
function action(kind,value){if(kind==='activate'){if(autoPaused){autoPaused=false;audio.pause(paused||rotated||!game);}return;}if(kind==='pause'){if(game){if(paused)closeModal();else settings();}return;}if(kind==='shop'){if(game?.clutch){hint('残局无需购买 · 武器在关卡开始时选择');return;}if(game?.mode==='spike'){if(game.phase==='buy')showShop();else hint('购买阶段结束 · 下回合可继续购买');}return;}if(!game||paused||rotated||game.winner!==null)return;const p=game.player;if(kind==='device'){if(!game.useDevice?.())hint('装置本回合已使用，或当前无法启动');return;}if(kind==='reload'){game.reload?.(p);return;}if(kind==='attack')game.attack(p);if(kind==='cast'){const ok=game.cast(p,value);const b=$(`[data-skill="${value}"]`);if(!ok&&p.cd[value]<=0&&!p.dead){hint(game.status(p,'suppressed')?'正在被脉冲压制，暂时不能施法':p.mana<[18,22,26,50][value]?'蓝量不足':HEROES[p.hero].desc[value]);}else if(ok){b.animate([{filter:'brightness(1.6)'},{filter:'brightness(1)'}],{duration:180});}}if(kind==='interact'&&!game.interact(p))hint('靠近旋转石门、A Drop上沿或终极法球，再点机关');if(kind==='recall')game.recall(p);}
$$('[data-skill]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();action('cast',+b.dataset.skill);});b.addEventListener('click',()=>action('cast',+b.dataset.skill));b.addEventListener('pointerenter',()=>{if(game)hint(`${HEROES[hero].skills[+b.dataset.skill]} · ${HEROES[hero].desc[+b.dataset.skill]}`);});});$('#attack').onclick=()=>action('attack');$('#recall').onclick=()=>action('recall');$('#interact').onclick=()=>action('interact');
function fmt(t){return `${Math.floor(t/60).toString().padStart(2,'0')}:${Math.floor(t%60).toString().padStart(2,'0')}`;}
function hint(text){$('#skillHint').textContent=text;$('#skillHint').classList.add('show');clearTimeout(window.hintTimer);window.hintTimer=setTimeout(()=>$('#skillHint').classList.remove('show'),2800);}
function announce(text){$('#announcement').textContent=text;$('#announcement').classList.add('show');noticesUntil=performance.now()+1500;}
function clutchBrief(){const m=game.mission;modal(`<div class="clutch-brief"><div class="eyebrow">CLUTCH LAB · 第 ${game.stage+1} / 3 关</div><h2>${m.name}</h2><div class="clutch-tag">${m.tag} · ${m.seconds} 秒</div><p>${m.hint}</p><div class="clutch-facts"><span>独自行动</span><span>无死亡等待</span><span>失败立即重试</span></div><h3>选择主武器</h3><div class="clutch-loadout">${['vandal','phantom','spectre'].map((id,i)=>`<button data-clutch-gun="${id}" class="${i===0?'selected':''}">${gunIcon(GUNS[id])}<b>${GUNS[id].name}</b></button>`).join('')}</div><h3>一次战术装置</h3><div class="device-options">${Object.entries(DEVICES).map(([id,d])=>`<button data-clutch-device="${id}" class="${id==='scan'?'selected':''}"><b>${d.name}</b><small>${d.desc}</small></button>`).join('')}</div><p class="clutch-controls">WASD / 摇杆移动 · 空格 / 开火按钮射击 · Q E R F 技能 · Y 装置 · T 换弹 · G 拆包</p><button id="launchClutch" class="primary">开始挑战 ↗</button><button id="leaveClutch">返回选人</button></div>`,'brief');let gun='vandal',device='scan';$$('[data-clutch-gun]').forEach(b=>b.onclick=()=>{gun=b.dataset.clutchGun;$$('[data-clutch-gun]').forEach(x=>x.classList.toggle('selected',x===b));});$$('[data-clutch-device]').forEach(b=>b.onclick=()=>{device=b.dataset.clutchDevice;$$('[data-clutch-device]').forEach(x=>x.classList.toggle('selected',x===b));});$('#launchClutch').onclick=()=>{game.begin(gun,device);$('#modal').classList.add('hidden');pause(false);};$('#leaveClutch').onclick=backLobby;}
function clutchResult(){const g=game,r=g.summary,won=r.won,history=[...g.history,r],total=history.reduce((n,x)=>n+x.points,0);let best=0;try{best=Number(localStorage.getItem('lotus-clutch-best')||0);if(won&&g.stage===2&&total>best){best=total;localStorage.setItem('lotus-clutch-best',String(best));}}catch{}audio.play(won?'level':'end');modal(`<div class="clutch-brief"><div class="eyebrow">CLUTCH LAB · ${g.stage+1} / 3</div><h2>${won?'残局拿下！':'再换一种打法。'}</h2><div class="clutch-stars">${'★'.repeat(r.stars)}${'☆'.repeat(3-r.stars)}</div><p>${r.reason}</p><div class="report-metrics"><div><b>${r.time}s</b><span>用时</span></div><div><b>${r.kills}</b><span>击杀</span></div><div><b>${r.damage}</b><span>伤害</span></div><div><b>${total}</b><span>累计得分</span></div></div><p>${won?'三星条件：获胜 · 剩余生命≥50 · 用时≤时限70%':'建议：侦察确认角落，技能隔断枪线，避免同时暴露在两名敌人面前。'}</p>${won&&g.stage<2?`<h3>下一关，选择一种强化</h3><div class="augment-grid">${AUGMENTS.filter(a=>!g.augments.includes(a.id)).map(a=>`<button data-augment="${a.id}"><b>${a.name}</b><small>${a.desc}</small><span>带入下一关 ↗</span></button>`).join('')}</div>`:''}${won&&g.stage===2?`<p>三关通关 · 本机最佳 ${best} 分</p><button id="newClutch" class="primary">新的三关挑战 ↗</button>`:''}<div class="modal-buttons"><button id="retryClutch">重试本关</button><button id="clutchLobby">返回选人</button></div></div>`,'result');$$('[data-augment]').forEach(b=>b.onclick=()=>start(g.stage+1,[...g.augments,b.dataset.augment],history));$('#retryClutch').onclick=()=>start(g.stage,g.augments,g.history,g.initialSeed);$('#clutchLobby').onclick=backLobby;if($('#newClutch'))$('#newClutch').onclick=()=>start();}

function settlement(){if(game.clutch){clutchResult();return;}pause(true);audio.pause(false);audio.play('end');setTimeout(()=>audio.pause(true),1300);const p=game.player,won=game.winner===0,spike=game.mode==='spike';const allies=game.entities.filter(e=>e.kind==='hero'&&e.team===0);const enemies=game.entities.filter(e=>e.kind==='hero'&&e.team===1);const rows=(arr,team)=>arr.map(e=>`<tr class="${e.player?'you':''}"><td style="color:${team?'#f1ad98':'#b0dfb9'}">${HEROES[e.hero].name}${e.player?' · 你':''}</td><td>${e.kills} / ${e.deaths} / ${e.assists}</td><td>Lv.${e.level}</td><td>${team?'敌方':'我方'}</td></tr>`).join('');modal(`<div class="result-kicker">ANCIENT CITY / MATCH COMPLETE</div><div class="results-title">${won?'胜利':'惜败'}</div><p style="text-align:center;margin:3px 0">${spike?`五回合完赛 · ${game.roundScore[0]} : ${game.roundScore[1]}`:won?'敌方水晶已被摧毁。':'我方水晶已被摧毁，再次集结。'} · ${fmt(game.time)}</p><div class="result-grid"><div><strong>${p.kills}/${p.deaths}/${p.assists}</strong><span>击杀 / 阵亡 / 助攻</span></div><div><strong>${Math.round(game.stats.damage)}</strong><span>造成伤害</span></div><div><strong>${spike?game.results.filter(r=>r.survived).length:game.stats.lastHits}</strong><span>${spike?'存活回合':'小兵补刀'}</span></div><div><strong>${Math.round(game.stats.healing)}</strong><span>治疗量</span></div></div><table class="results-table"><thead><tr><th>英雄</th><th>K / D / A</th><th>等级</th><th>队伍</th></tr></thead><tbody>${rows(allies,0)}${rows(enemies,1)}</tbody></table>${spike?historyHTML():''}<div class="modal-buttons"><button id="again">再来一局</button><button id="chooseAgain">重新选人</button></div>`,'result');$('#again').onclick=()=>start();$('#chooseAgain').onclick=backLobby;}
function processEvents(){for(const ev of game.events){if(eventSeen.has(ev))continue;eventSeen.add(ev);view.feedback(ev,game);const audible=ev.x===undefined||dist(game.player,ev)<40;if(ev.type==='spellImpact'&&audible)audio.play('impact');if(ev.type==='cast'&&audible)audio.play('cast',ev.hero);if(ev.type==='attack'&&audible){audio.play(ev.weapon?'gun':'attack',ev.weapon?GUNS[ev.weapon]?.category:ev.hero);if(ev.player&&!ev.hasTarget&&game.time>(game.lastEmptyAttackHint||0)){hint('普攻已释放 · 接近目标或点击敌人锁定');game.lastEmptyAttackHint=game.time+8;}}if(ev.type==='hit'&&ev.important){audio.play('hit');if(ev.target===game.player.id){document.body.classList.add('taking-hit');clearTimeout(window.hitTimer);window.hitTimer=setTimeout(()=>document.body.classList.remove('taking-hit'),110);}}if(ev.type==='level'&&ev.id===game.player.id){announce(`等级提升 · LV. ${ev.level}`);audio.play('level');}if(ev.type==='gate'&&audible)audio.play('gate');if(ev.type==='break'&&audible)audio.play('break');if(ev.type==='zip')audio.play('zip');if(ev.type==='notice')hint(ev.text);if(ev.type==='orb'){audio.play('level');if(ev.id===game.player.id)announce('终极法球 · 大招冷却 −12秒');}if(ev.type==='buff'&&ev.hero===game.player.id)announce(`获得 ${BUFFS[ev.buff].name} buff · ${BUFFS[ev.buff].desc}`);if(ev.type==='announce')hint(ev.text);if(ev.type==='kill'){audio.play('kill');const killer=ev.killer<0?'守卫':HEROES[ev.killer].name;feed.unshift({text:`${killer}  ⚔  ${HEROES[ev.victim].name}`,team:ev.team,until:game.time+6});if(ev.player){announce(`${ev.streak>1?ev.streak+' 连斩 · ':''}击败 ${HEROES[ev.victim].name}`);document.body.classList.add('scored-kill');setTimeout(()=>document.body.classList.remove('scored-kill'),450);}}if(ev.type==='reload'&&ev.player)audio.play('reload');if(ev.type==='beep')audio.play('beep');if(ev.type==='plant'){audio.play('plant');announce(`${ev.site} 点已安装 Spike · 45秒`);}if(ev.type==='defuse')audio.play('defuse');if(ev.type==='detonate')audio.play('impact');if(ev.type==='roundStart')hint(`第 ${ev.round} / 5 回合 · ${ev.role} · ${ev.role==='进攻方'?'前往 A/B/C 包点安装':'守住包点，阻止安装'}`);if(ev.type==='roundEnd'&&game.winner===null)roundPanel(ev);if(ev.type==='end')settlement();}}
function ui(){const p=game.player;const blind=Math.max(0,(p.status.blind||0)-game.time);$('#blindOverlay').style.opacity=blind>0?String(Math.min(.92,blind/.6)):'0';$('#blindOverlay').classList.toggle('active',blind>0);$('#focusGame').textContent=autoPaused?'点击画面继续 · WASD':'WASD 移动 · 空格开火';const sp=game.mode==='spike';$('#timer').textContent=sp?(game.phase==='buy'?'购买阶段':fmt(game.spike.state==='planted'?game.spike.remaining:game.roundTime)):fmt(game.time);$('#blueScore').textContent=(sp?game.roundScore:game.score)[0];$('#redScore').textContent=(sp?game.roundScore:game.score)[1];$('#wave').textContent=game.clutch?'残局 '+(game.stage+1)+'/3':sp?`ROUND ${game.round+1}/5`:'WAVE '+String(game.wave).padStart(2,'0');$('#kda').textContent=`${p.kills} / ${p.deaths} / ${p.assists}`;$('#level').textContent=game.clutch?'★ '+game.history.reduce((n,r)=>n+r.stars,0):sp?'¤ '+p.wallet:'LV. '+p.level;$('#level').title=`经验 ${Math.floor(p.xp)} / ${80+p.level*30}`;$('#hpBar').style.width=100*p.hp/p.maxHp+'%';$('#mpBar').style.width=100*p.mana/p.maxMana+'%';$('#hpText').textContent=`${Math.ceil(p.hp)} / ${p.maxHp}${p.shield?' +'+Math.ceil(p.shield):''}`;$('#buffs').innerHTML=sp?`<span>${GUNS[p.weapon].name} · ${p.reloadUntil>game.time?'换弹 '+(p.reloadUntil-game.time).toFixed(1)+'s':GUNS[p.weapon].mag?p.mag+' / '+p.reserve:'近战'} · 护甲 ${Math.ceil(p.armor)}</span>`:BUFFS.filter(b=>game.buff(p,b.id)).map(b=>`<span style="color:${b.color}">${b.name} ${Math.ceil(p.buffs[b.id]-game.time)}s</span>`).join('')||`<span style="opacity:.6">蓝量 ${Math.floor(p.mana)} / 120</span>`;$$('[data-skill]').forEach((b,i)=>{const cd=p.cd[i],disabled=p.dead||game.status(p,'suppressed')||game.status(p,'stun')||p.mana<[18,22,26,50][i];b.classList.toggle('empty',disabled);b.querySelector('.cooldown').textContent=cd>0?Math.ceil(cd):disabled?p.dead?sp?'已阵亡':'复活中':game.status(p,'suppressed')?'压制':game.status(p,'stun')?'眩晕':'缺蓝':'';b.querySelector('.cooldown').style.opacity=cd>0||disabled?'1':'0';});$('#deathNotice').classList.toggle('hidden',!p.dead);if(p.dead)$('#deathNotice').innerHTML=sp?`<small>COMBAT REPORT</small><b>本回合已阵亡</b>${game.lastDeath?`<span>${game.lastDeath.hero===undefined?'防守炮台':HEROES[game.lastDeath.hero].name} · ${game.lastDeath.skill?'技能命中':GUNS[game.lastDeath.weapon]?.name||'攻击'}</span><span>最近8秒承受 ${game.lastDeath.incoming} 伤害</span>`:''}<em>正在观战队友 · 仍可指挥包点</em>`:`等待复活<br><b>${Math.max(0,Math.ceil(p.respawn-game.time))} 秒</b>`;feed=feed.filter(e=>e.until>game.time).slice(0,4);$('#killFeed').innerHTML=feed.map(e=>`<div class="${e.team===0?'friendly':'enemy'}">${e.text}</div>`).join('');$('#aimToggle').classList.toggle('selected',controls.aiming);if(sp){const ch=game.channel,carrier=game.entities.find(e=>e.id===game.spike.carrier);$('#objectiveLabel').textContent=game.spike.state==='planted'?'拆包 G':'安包 G';$('#objective').textContent=ch?`${ch.type==='plant'?'安装':'拆除'}中 ${ch.progress.toFixed(1)} / ${ch.total}s ${'▰'.repeat(Math.ceil(ch.progress/ch.total*12))}`:game.phase==='buy'?`${game.role} · 选择装备后出发`:game.spike.state==='planted'?`${game.spike.site} 点已安装 · ${game.role==='防守方'?'靠近后长按安拆 G':'守住 Spike'} · ${Math.ceil(game.spike.remaining)}秒`:`${game.role} · ${carrier?.player?'你携带 Spike，进入包点长按安包 G':game.spike.state==='dropped'?'Spike 掉落，进攻方靠近拾取':game.role==='进攻方'?'跟随持包队友进攻 A/B/C':'守住 A/B/C，可拆除敌方 Spike'}`;}else{const exposed=game.entities.find(e=>e.kind==='core'&&e.team===1);$('#objective').textContent=autoPaused?'点击画面或按 WASD 继续':game.vulnerable(exposed)?'敌方水晶已暴露 · 集结进攻！':game.time<35?'跟随兵线，先攻破一路双塔。':`旋转石门 ${game.gates[0].open?'已开启':'已关闭'} · 靠近后 X 交互`;}const liveAllies=game.entities.filter(e=>e.kind==='hero'&&e.team===0&&!e.dead).length,liveEnemies=game.entities.filter(e=>e.kind==='hero'&&e.team===1&&!e.dead).length;$('#aliveCount').textContent=`存活 ${liveAllies} : ${liveEnemies}`;$('#orderStatus').textContent=ORDERS[game.order?.kind||'auto'];$$('[data-order]').forEach(b=>b.classList.toggle('selected',b.dataset.order===(game.order?.kind||'auto')));$('#deviceUse').textContent=sp?`${DEVICES[game.device].name} ${game.deviceUsed?'已用':'Y'}`:'';$('#deviceUse').disabled=!!game.deviceUsed||p.dead;$('#passSpike').disabled=!sp||p.dead||game.spike.state!=='carried'||game.spike.carrier!==p.id;$('#squadStatus').innerHTML=game.entities.filter(e=>e.kind==='hero'&&e.team===0&&!e.player).map(e=>`<span class="${e.dead?'dead':''}">${HEROES[e.hero].name} <b>${e.dead?'阵亡':e.task||'自主推进'}</b></span>`).join('');const nav=game.navigation;$('#navStatus').textContent=game.navigationEnabled?(nav?`${nav.label} · ${nav.metres>0?nav.metres+'m'+(nav.reached?'':' · 前路受阻'):nav.reached?'已抵达':'前路受阻'}`:'选择包点指令显示路线'):'路线引导已关闭';$('#navToggle').classList.toggle('selected',!!game.navigationEnabled);if(game.clutch&&game.time<game.playerProtectionUntil)$('#buffs').innerHTML+='<span>部署保护 '+Math.ceil(game.playerProtectionUntil-game.time)+'s</span>';if(game.clutch){$('.scoreboard small').textContent=game.mission.tag;$('#blueScore').textContent='你';$('#redScore').textContent=liveEnemies;$('#objective').textContent=game.channel?`拆包中 ${game.channel.progress.toFixed(1)} / 7s`:`${game.mission.name} · ${game.mission.type==='retake'?'清点后长按 G 拆包':game.mission.type==='hold'?'阻止敌人拆包，等候引爆':'70秒内清除守卫'}`;}view.minimap(game,$('#minimap'));document.body.dataset.gameState=window.render_game_to_text();}
try{view=new View($('#world'),$('#labels'));view.renderer.domElement.tabIndex=0;view.renderer.domElement.setAttribute('aria-label','游戏画面，点击后使用WASD移动');controls=new Controls($('#joystick'),$('#attack'),action);choose(0);$('#loading').classList.add('hidden');}catch(e){$('#loading').innerHTML='当前浏览器无法启动 3D 场景。<br>请使用支持 WebGL2 的新版 Safari 或 Chrome。';console.error(e);}
function loop(now){const dt=Math.min(.05,(now-last)/1000);last=now;frameTimes.push(dt);if(frameTimes.length>60)frameTimes.shift();fps=1/(frameTimes.reduce((a,b)=>a+b,0)/frameTimes.length);if(game&&!paused&&!autoPaused&&!rotated&&!document.hidden){const input=controls.value();game.showAttackRange=input.attack;$('#attack').classList.toggle('firing',input.attack);game.update(dt,input);processEvents();}if(view&&!rotated){view.draw(game,dt,now/1000);if(game&&now>uiAt){uiAt=now+100;ui();}}if(game&&rotated)document.body.dataset.gameState=window.render_game_to_text();if(noticesUntil&&now>noticesUntil){$('#announcement').classList.remove('show');noticesUntil=0;}requestAnimationFrame(loop);}requestAnimationFrame(loop);
const media=matchMedia('(orientation:portrait)');media.addEventListener('change',e=>{rotated=e.matches;controls?.reset();audio.pause(rotated||paused||!game||game.winner!==null);});document.addEventListener('visibilitychange',()=>{if(document.hidden&&game){autoPaused=true;controls?.reset();audio.pause(true);}});window.addEventListener('blur',()=>{if(game){autoPaused=true;controls?.reset();audio.pause(true);}});window.addEventListener('focus',()=>{if(game&&!paused){autoPaused=false;audio.pause(rotated||game.winner!==null);}});document.addEventListener('pointerdown',e=>{if(autoPaused){autoPaused=false;audio.pause(paused||rotated||!game);}if(game&&!paused&&e.pointerType!=='touch'){const canvas=$('#world canvas');canvas?.focus({preventScroll:true});}},true);
// Read-only diagnostics for browser QA; no gameplay mutation interface.
window.render_game_to_text=()=>JSON.stringify({state:game?(game.winner!==null?'ended':paused||autoPaused||rotated?'paused':'playing'):'lobby',difficulty,selected:HEROES[hero].name,portrait:rotated,mode:selectedMode,fps:Math.round(fps),...(game?game.snapshot():{}),render:view?{calls:view.renderer.info.render.calls,triangles:view.renderer.info.render.triangles}:null});
$('#world').addEventListener('pointerdown',e=>{if(!game||paused||rotated)return;const point=view.toWorld(e.clientX,e.clientY);const t=game.entities.filter(t=>!t.dead&&t.team!==game.player.team&&t.team<3&&dist(t,point)<4&&!game.status(t,'invis')).sort((a,b)=>dist(a,point)-dist(b,point))[0];game.lockTarget=t?.id||null;game.player.angle=Math.atan2(point.x-game.player.x,point.z-game.player.z);if(t)hint(`锁定${t.kind==='hero'?HEROES[t.hero].name:t.kind==='camp'?'野怪':'建筑'} · 金色标记`);});
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});

$('#shop').onclick=()=>action('shop');$('#aimToggle').onclick=()=>{controls.aiming=!controls.aiming;hint(controls.aiming?'精准瞄准 · 停步首发更准':'恢复移动射击');};const objectiveButton=$('#objectiveHold');objectiveButton.addEventListener('pointerdown',e=>{e.preventDefault();objectiveButton.setPointerCapture(e.pointerId);controls.objectiveHeld=true;});for(const type of ['pointerup','pointercancel','lostpointercapture'])objectiveButton.addEventListener(type,()=>controls.objectiveHeld=false);

function syncDisplay(){const v=viewportMetrics(innerWidth,innerHeight,document.documentElement.clientHeight,window.visualViewport);for(const [name,value]of Object.entries({'scene-height':v.sceneHeight,'hud-height':v.hudHeight,'hud-top':v.hudTop}))document.documentElement.style.setProperty('--'+name,value+'px');requestAnimationFrame(()=>{view?.resize();controls?.reset();});const full=!!(document.fullscreenElement||document.webkitFullscreenElement)||displayState().standalone;$('#fullscreen').setAttribute('aria-label',full?'退出全屏':'全屏');}
for(const name of ['fullscreenchange','webkitfullscreenchange'])document.addEventListener(name,syncDisplay);window.addEventListener('resize',syncDisplay);window.addEventListener('pageshow',syncDisplay);window.visualViewport?.addEventListener('resize',syncDisplay);window.visualViewport?.addEventListener('scroll',syncDisplay);screen.orientation?.addEventListener('change',syncDisplay);syncDisplay();

const orderPanel=document.createElement('div');orderPanel.id='commandPanel';orderPanel.innerHTML=`<div class="command-title"><span>战术指挥 <b id="orderStatus">自主配合</b></span><span id="aliveCount">存活 5 : 5</span></div><div class="order-buttons">${Object.entries(ORDERS).map(([id,n])=>`<button data-order="${id}" title="${n}" aria-label="指挥：${n}">${id==='auto'?'自主':id==='follow'?'跟随':id==='hold'?'守点':id}</button>`).join('')}</div><div id="squadStatus"></div>`;$('#hud').append(orderPanel);$$('[data-order]').forEach(b=>b.onclick=()=>{if(game&&!paused)game.command(b.dataset.order);});const deviceUse=document.createElement('button');deviceUse.id='deviceUse';deviceUse.className='spike-only';deviceUse.onclick=()=>action('device');$('#hud').append(deviceUse);const passButton=document.createElement('button');passButton.id='passSpike';passButton.className='spike-only';passButton.textContent='交包队友';passButton.onclick=()=>{if(!game||paused)return;if(!game.passSpike?.())hint('携包时靠近存活队友7米内，可交包让队友安装');};$('#hud').append(passButton);

const navPanel=document.createElement('div');navPanel.id='navigationPanel';navPanel.innerHTML='<button id="navToggle" class="selected" aria-label="开关路线引导">⌁ 路线</button><span id="navStatus">沿光点推进</span>';$('#hud').append(navPanel);$('#navToggle').onclick=()=>{if(game){game.navigationEnabled=!game.navigationEnabled;if(!game.navigationEnabled)game.navigation=null;}};refreshMode();
